import React, { useEffect, useRef } from "react";
import { MapContainer, TileLayer, GeoJSON, Popup, CircleMarker, Polyline } from "react-leaflet";
import L from "leaflet";
import { Box, Typography, Chip, CircularProgress } from "@mui/material";
import "leaflet/dist/leaflet.css";

// Fix for default markers in react-leaflet
delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl: require("leaflet/dist/images/marker-icon-2x.png"),
  iconUrl: require("leaflet/dist/images/marker-icon.png"),
  shadowUrl: require("leaflet/dist/images/marker-shadow.png"),
});

const MapVisualization = ({ stressData, ratingsData, loading }) => {
  const mapRef = useRef();

  // Focused bounds around the transmission network area
  const networkBounds = [
    [21.25, -157.95], // Southwest corner (focused on Oahu)
    [21.46, -157.68], // Northeast corner (focused on Oahu)
  ];

  // Create bus coordinates lookup using actual bus data
  const getBusCoordinates = (busId) => {
    // Real coordinates from the Hawaiian grid data (lat, lng)
    const busCoords = {
      1: [21.344246, -157.939889], // ALOHA138
      2: [21.344246, -157.939889], // ALOHA69
      3: [21.347927, -157.876274], // FLOWER69
      4: [21.293143, -157.848767], // WAVE69
      5: [21.316548, -157.845053], // HONOLULU138
      6: [21.316548, -157.845053], // HONOLULU69
      7: [21.291518, -157.826869], // SURF69
      8: [21.451733, -157.824227], // KANEOHE69
      9: [21.273462, -157.822444], // TURTLE138
      10: [21.273462, -157.822444], // TURTLE69
      11: [21.35548, -157.821663], // Bus 11
      12: [21.32021, -157.810758], // Bus 12
      13: [21.290612, -157.788328], // Bus 13
      14: [21.395084, -157.758188], // Bus 14
      15: [21.395084, -157.758188], // Bus 15
      16: [21.311063, -157.750269], // Bus 16
      17: [21.335013, -157.710924], // Bus 17
      18: [21.294518, -157.688748], // Bus 18
      19: [21.417374, -157.936867], // Bus 19
      20: [21.417374, -157.936867], // Bus 20
      21: [21.417374, -157.936867], // Bus 21
      22: [21.417374, -157.936867], // Bus 22
      23: [21.417374, -157.936867], // Bus 23
      24: [21.417374, -157.936867], // Bus 24
      25: [21.417374, -157.936867], // Bus 25
    };

    return busCoords[busId] || [21.3 + (busId % 10) * 0.01, -157.9 + (busId % 8) * 0.01];
  };

  const getStatusColor = (status) => {
    switch (status) {
      case "GOOD":
        return "#4caf50";
      case "WARN":
        return "#ff9800";
      case "BAD":
        return "#f44336";
      default:
        return "#9e9e9e";
    }
  };

  const getUtilizationColor = (utilization) => {
    if (utilization >= 100) return "#f44336"; // Red
    if (utilization >= 80) return "#ff9800"; // Orange
    return "#4caf50"; // Green
  };

  const getLineWeight = (utilization) => {
    // Scale line weight based on utilization (4-12px) - increased for better visibility
    return Math.max(4, Math.min(12, 4 + (utilization / 100) * 8));
  };

  // Create transmission lines
  const createTransmissionLines = () => {
    if (!stressData || stressData.length === 0) return [];

    return stressData.map((line) => {
      const bus0Coords = getBusCoordinates(line.bus0);
      const bus1Coords = getBusCoordinates(line.bus1);

      const lineColor = getUtilizationColor(line.utilization_pct);
      const lineWeight = getLineWeight(line.utilization_pct);

      return (
        <Polyline key={line.line_id} positions={[bus0Coords, bus1Coords]} color={lineColor} weight={lineWeight} opacity={0.8}>
          <Popup>
            <Box sx={{ minWidth: 200 }}>
              <Typography variant="h6" gutterBottom>
                Line: {line.line_id}
              </Typography>
              <Typography variant="body2" gutterBottom>
                <strong>From:</strong> {line.bus0_name} (Bus {line.bus0})
                <br />
                <strong>To:</strong> {line.bus1_name} (Bus {line.bus1})
                <br />
                <strong>Conductor:</strong> {line.conductor}
                <br />
                <strong>Voltage:</strong> {line.voltage_kv} kV
                <br />
                <strong>MOT:</strong> {line.mot_c}°C
              </Typography>
              <Box sx={{ mt: 1 }}>
                <Chip label={`${line.utilization_pct.toFixed(1)}% Utilization`} color={line.utilization_pct >= 100 ? "error" : line.utilization_pct >= 80 ? "warning" : "success"} size="small" />
              </Box>
              <Typography variant="body2" sx={{ mt: 1 }}>
                <strong>Rating:</strong> {line.rating_amps.toFixed(0)} A ({line.rating_mva.toFixed(1)} MVA)
                <br />
                <strong>Flow:</strong> {line.flow_amps.toFixed(0)} A ({line.flow_mva.toFixed(1)} MVA)
                <br />
                <strong>Margin:</strong> {(line.rating_amps - line.flow_amps).toFixed(0)} A
              </Typography>
            </Box>
          </Popup>
        </Polyline>
      );
    });
  };

  // Create bus markers
  const createBusMarkers = () => {
    if (!stressData || stressData.length === 0) return [];

    const uniqueBuses = new Set();
    stressData.forEach((line) => {
      uniqueBuses.add(line.bus0);
      uniqueBuses.add(line.bus1);
    });

    return Array.from(uniqueBuses).map((busId) => {
      const coords = getBusCoordinates(busId);
      const busData = stressData.find((line) => line.bus0 === busId || line.bus1 === busId);
      const busName = busData ? (busData.bus0 === busId ? busData.bus0_name : busData.bus1_name) : `Bus ${busId}`;
      const voltage = busData ? busData.voltage_kv : "Unknown";

      // Size markers based on voltage level - increased for better visibility
      const getBusSize = (voltage) => {
        if (voltage >= 138) return 12; // 138kV and above - larger
        if (voltage >= 69) return 10; // 69kV - medium
        return 8; // Lower voltages - smaller
      };

      const getBusColor = (voltage) => {
        if (voltage >= 138) return "#d32f2f"; // Red for high voltage
        if (voltage >= 69) return "#1976d2"; // Blue for medium voltage
        return "#388e3c"; // Green for lower voltage
      };

      return (
        <CircleMarker key={`bus-${busId}`} center={coords} radius={getBusSize(voltage)} color={getBusColor(voltage)} fillColor={getBusColor(voltage)} fillOpacity={0.8} weight={2}>
          <Popup>
            <Box sx={{ minWidth: 150 }}>
              <Typography variant="h6" gutterBottom>
                {busName}
              </Typography>
              <Typography variant="body2">
                <strong>Bus ID:</strong> {busId}
                <br />
                <strong>Voltage:</strong> {voltage} kV
                <br />
                <strong>Coordinates:</strong> {coords[0].toFixed(4)}, {coords[1].toFixed(4)}
              </Typography>
            </Box>
          </Popup>
        </CircleMarker>
      );
    });
  };

  useEffect(() => {
    if (mapRef.current && stressData.length > 0) {
      // Fit map to show all transmission lines with better padding
      const allCoords = [];
      stressData.forEach((line) => {
        allCoords.push(getBusCoordinates(line.bus0));
        allCoords.push(getBusCoordinates(line.bus1));
      });

      if (allCoords.length > 0) {
        // Add some padding around the network
        const bounds = L.latLngBounds(allCoords);
        const paddedBounds = bounds.pad(0.1); // 10% padding
        mapRef.current.fitBounds(paddedBounds, { padding: [30, 30] });
      }
    }
  }, [stressData]);

  return (
    <Box sx={{ height: "500px", position: "relative" }}>
      <Typography variant="h6" gutterBottom>
        Grid Line Status Map
      </Typography>

      {loading && (
        <Box
          sx={{
            position: "absolute",
            top: "50%",
            left: "50%",
            transform: "translate(-50%, -50%)",
            zIndex: 1000,
            backgroundColor: "rgba(255, 255, 255, 0.8)",
            borderRadius: 1,
            p: 2,
          }}
        >
          <CircularProgress />
          <Typography variant="body2" sx={{ mt: 1 }}>
            Loading data...
          </Typography>
        </Box>
      )}

      <MapContainer
        ref={mapRef}
        center={[21.35, -157.82]} // Centered on the transmission network
        zoom={10} // Higher zoom level to show more detail
        style={{ height: "100%", width: "100%" }}
        bounds={networkBounds}
        boundsOptions={{ padding: [20, 20] }}
      >
        <TileLayer attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors' url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" />

        {/* Render transmission lines */}
        {createTransmissionLines()}

        {/* Render bus markers */}
        {createBusMarkers()}
      </MapContainer>

      {/* Legend */}
      <Box sx={{ mt: 2 }}>
        <Typography variant="body2" gutterBottom>
          <strong>Legend:</strong>
        </Typography>
        <Box sx={{ display: "flex", gap: 1, flexWrap: "wrap", alignItems: "center", mb: 1 }}>
          <Typography variant="body2" sx={{ mr: 1 }}>
            <strong>Transmission Lines:</strong>
          </Typography>
          <Chip label="Good (<80%)" color="success" size="small" />
          <Chip label="Warning (80-100%)" color="warning" size="small" />
          <Chip label="Overloaded (≥100%)" color="error" size="small" />
          <Typography variant="body2" sx={{ ml: 2 }}>
            Color and thickness indicate utilization level
          </Typography>
        </Box>
        <Box sx={{ display: "flex", gap: 1, flexWrap: "wrap", alignItems: "center" }}>
          <Typography variant="body2" sx={{ mr: 1 }}>
            <strong>Bus/Substations:</strong>
          </Typography>
          <Box sx={{ display: "flex", alignItems: "center", gap: 0.5 }}>
            <div style={{ width: 12, height: 12, borderRadius: "50%", backgroundColor: "#d32f2f" }}></div>
            <Typography variant="body2">138kV+</Typography>
          </Box>
          <Box sx={{ display: "flex", alignItems: "center", gap: 0.5, ml: 1 }}>
            <div style={{ width: 10, height: 10, borderRadius: "50%", backgroundColor: "#1976d2" }}></div>
            <Typography variant="body2">69kV</Typography>
          </Box>
          <Box sx={{ display: "flex", alignItems: "center", gap: 0.5, ml: 1 }}>
            <div style={{ width: 8, height: 8, borderRadius: "50%", backgroundColor: "#388e3c" }}></div>
            <Typography variant="body2">Lower</Typography>
          </Box>
        </Box>
      </Box>
    </Box>
  );
};

export { MapVisualization };
